package com.realize.app.data

import androidx.room.Entity
import androidx.room.PrimaryKey
import java.util.Calendar
import java.util.concurrent.TimeUnit

/**
 * Represents a student assignment or academic task in the Realize app.
 *
 * @param id Unique identifier generated by Room database.
 * @param title Name of the assignment (e.g., "DSA Graph Algorithms").
 * @param subject Course or subject (e.g., "Data Structures", "Physics").
 * @param dueDateTimeMillis Timestamp in milliseconds when the assignment is due.
 * @param notes Additional details or instructions.
 * @param isCompleted True if the user has marked this assignment as finished.
 * @param createdAt Creation timestamp in milliseconds.
 */
@Entity(tableName = "assignments")
data class Assignment(
    @PrimaryKey(autoGenerate = true)
    val id: Long = 0,
    val title: String,
    val subject: String,
    val dueDateTimeMillis: Long,
    val notes: String = "",
    val isCompleted: Boolean = false,
    val createdAt: Long = System.currentTimeMillis()
) {
    val daysLeftText: String
        get() {
            val todayMidnight = Calendar.getInstance().apply {
                set(Calendar.HOUR_OF_DAY, 0)
                set(Calendar.MINUTE, 0)
                set(Calendar.SECOND, 0)
                set(Calendar.MILLISECOND, 0)
            }
            val dueMidnight = Calendar.getInstance().apply {
                timeInMillis = dueDateTimeMillis
                set(Calendar.HOUR_OF_DAY, 0)
                set(Calendar.MINUTE, 0)
                set(Calendar.SECOND, 0)
                set(Calendar.MILLISECOND, 0)
            }
            val diffDays = TimeUnit.MILLISECONDS.toDays(
                dueMidnight.timeInMillis - todayMidnight.timeInMillis
            )
            return when {
                diffDays < 0 -> {
                    val overdueDays = -diffDays
                    if (overdueDays == 1L) "1 day overdue" else "$overdueDays days overdue"
                }
                diffDays == 0L -> "Due Today"
                diffDays == 1L -> "Due Tomorrow"
                else -> "$diffDays days left"
            }
        }
}
